/** Generate the Lua configuration for an agent-owned nested Hyprland desktop. */
import { mkdir, rename, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { ErrorCode, HyprscopeError } from '../errors.ts'
import { BIND_DESCRIPTION, DEFAULT_PANIC_KEY, normalizedKey } from '../lease/bind.ts'
import { digestDesktopConfig, readDesktopSnippets, type DesktopSnippet } from './hash.ts'

/** First line of the generated file; the rest of that line tells readers not to edit it. */
export const DESKTOP_CONFIG_MARKER = '-- generated by hyprscope control desktop'

/** Start of the block that inlines the agent's own Lua snippets. */
const SNIPPET_BEGIN = '-- >>> agent snippets >>>'

/** End of the block that inlines the agent's own Lua snippets. */
const SNIPPET_END = '-- <<< agent snippets <<<'

/** Generated file name below the Hyprland configuration directory. */
const CONFIG_FILE = 'hyprland.lua'

/** Directory below the Hyprland configuration directory that holds agent snippets. */
const AGENT_DIR = 'agent'

/** Monitor mode accepted by {@link validSize}. */
const SIZE_PATTERN = /^\d{2,5}x\d{2,5}$/

/** Values needed to render the generated configuration. */
export interface DesktopConfigInput {
  /** Monitor mode such as `1280x800`; `null` or omitted selects the preferred mode. */
  size?: string | null
  /** Shell command the panic shortcut runs. */
  panicCommand: string
}

/**
 * Test a monitor mode string.
 * @param size Candidate mode such as `1280x800`.
 * @returns Whether both sides have 2-5 digits and a positive value.
 */
export function validSize(size: string): boolean {
  if (typeof size !== 'string' || !SIZE_PATTERN.test(size)) return false
  const [width = '', height = ''] = size.split('x')
  return Number(width) > 0 && Number(height) > 0
}

/**
 * Render the generated Lua program without snippet files.
 *
 * The snippet block is present but empty, because only {@link writeDesktopConfig}
 * reads `agent/*.lua`; a caller that wants them inline must write the file through
 * that function. The program holds one monitor rule and one panic bind, and no
 * startup command or user keybind of its own.
 * @param input Size and panic command.
 * @returns Lua source ending in a newline.
 */
export function renderConfig(input: DesktopConfigInput): string {
  return renderProgram(monitorMode(input.size), input.panicCommand, [])
}

/**
 * Write the generated configuration and hash it together with the agent snippets.
 *
 * The snippets are embedded in `hyprland.lua` itself rather than loaded through
 * dofile or require: the Lua config provider does not execute that indirection
 * reliably on reload.
 * @param options Configuration directory, monitor size, panic command, and environment.
 * @returns Written file, its config hash, and the snippet basenames in order.
 */
export async function writeDesktopConfig(options: {
  /** `$XDG_STATE_HOME/hyprscope/desktop/config`; created with its `hypr/agent` children. */
  configDir: string
  /** Monitor mode such as `1280x800`; `null` or omitted selects the preferred mode. */
  size?: string | null
  /** Shell command the panic shortcut runs. */
  panicCommand: string
  /** Environment the caller resolved `configDir` from; accepted for a uniform option shape. */
  env?: NodeJS.ProcessEnv
}): Promise<{ file: string; hash: string; snippets: string[] }> {
  // Validate before creating anything so a bad size leaves no partial layout.
  const mode = monitorMode(options.size)
  const hyprDir = join(options.configDir, 'hypr')
  const agentDir = join(hyprDir, AGENT_DIR)
  await mkdir(agentDir, { recursive: true, mode: 0o700 })
  const snippets = await readDesktopSnippets(agentDir)
  const text = renderProgram(mode, options.panicCommand, snippets)
  const file = join(hyprDir, CONFIG_FILE)
  const temporary = `${file}.${process.pid}.tmp`
  await writeFile(temporary, text, { mode: 0o644 })
  await rename(temporary, file)
  return { file, hash: digestDesktopConfig(text, snippets), snippets: snippets.map(snippet => snippet.name) }
}

/**
 * Hash the generated file together with every agent snippet.
 *
 * The digest is SHA-256 over `hyprland.lua\0<content>\0` followed by
 * `agent/<basename>\0<content>\0` for each snippet in basename order. Snippets are
 * hashed explicitly even though the generated file inlines them, so a snippet
 * edit changes the hash before the file is regenerated. A missing generated file
 * contributes no bytes: an empty directory hashes like the empty string, while a
 * snippet still changes the digest.
 * @param configDir `$XDG_STATE_HOME/hyprscope/desktop/config`.
 * @returns Lower-case SHA-256 hex digest.
 */
export { hashDesktopConfig } from './hash.ts'

/**
 * Resolve the monitor mode and reject an unusable size before any file is written.
 * @param size Caller-supplied size.
 * @returns Mode string for `hl.monitor`.
 */
function monitorMode(size: string | null | undefined): string {
  if (size === undefined || size === null) return 'preferred'
  if (!validSize(size)) {
    throw new HyprscopeError(ErrorCode.USAGE, `Expected a monitor size like 1280x800, received ${JSON.stringify(size)}`, { size })
  }
  return size
}

/**
 * Render one Lua program with the agent snippets already inline.
 * @param mode Monitor mode.
 * @param panicCommand Shell command the panic shortcut runs.
 * @param snippets Agent snippets in basename order.
 * @returns Lua source ending in a newline.
 */
function renderProgram(mode: string, panicCommand: string, snippets: readonly DesktopSnippet[]): string {
  const lines = [
    `${DESKTOP_CONFIG_MARKER}; do not edit this file.`,
    '-- The agent may add binds and window rules under agent/*.lua; they are embedded below.',
    '',
    `hl.monitor({ output = "", mode = ${JSON.stringify(mode)}, scale = 1 })`,
    `hl.bind(${JSON.stringify(normalizedKey(DEFAULT_PANIC_KEY))}, hl.dsp.exec_cmd(${JSON.stringify(panicCommand)}), { description = ${JSON.stringify(BIND_DESCRIPTION)} })`,
    '',
    SNIPPET_BEGIN,
  ]
  for (const snippet of snippets) {
    lines.push(`-- agent/${snippet.name}`)
    lines.push(snippet.content.replace(/\n+$/, ''))
  }
  lines.push(SNIPPET_END, '')
  return lines.join('\n')
}
